        ["LedgerError"] = ["Unable to save alert record: {0}", "Záznam upozornění nelze uložit: {0}", "Nie można zapisać alertów: {0}", "Warnungsprotokoll nicht gespeichert: {0}", "No se puede guardar el registro de alertas: {0}"],
        ["LedgerReadError"] = ["Unable to read alert record: {0}", "Nelze načíst záznam upozornění: {0}", "Nie można odczytać alertów: {0}", "Warnungsprotokoll nicht lesbar: {0}", "No se puede leer el registro de alertas: {0}"],
        ["ServerChangeError"] = ["Unable to change server: {0}", "Server nelze změnit: {0}", "Nie można zmienić serwera: {0}", "Serverwechsel nicht möglich: {0}", "No se puede cambiar el servidor: {0}"],
